// Разбираем события Instagram: сообщения клиентов, эхо наших ответов, повторы
const st = $getWorkflowStaticData('global');
st.paused = st.paused || {};     // user_id -> до какого времени бот молчит (Алина ответила сама)
st.botSent = st.botSent || {};   // user_id -> последние тексты, отправленные ботом
st.seen = st.seen || [];         // id обработанных сообщений (Meta иногда присылает повторно)
const PAUSE_HOURS = 12;
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const entry of body.entry || []) {
    for (const m of entry.messaging || []) {
      const msg = m.message;
      if (!msg || msg.is_deleted) continue;
      if (msg.mid) { if (st.seen.includes(msg.mid)) continue; st.seen.push(msg.mid); }
      if (msg.is_echo) {
        // наше исходящее: если такого текста бот не отправлял — значит, ответил человек
        const client = m.recipient && m.recipient.id;
        const sent = st.botSent[client] || [];
        const i = sent.indexOf(msg.text || '');
        if (i >= 0) sent.splice(i, 1);
        else if (client) st.paused[client] = now + PAUSE_HOURS * 3600e3;
        continue;
      }
      const user_id = m.sender && m.sender.id;
      if (!user_id) continue;
      if ((st.paused[user_id] || 0) > now) continue;          // диалог ведёт человек
      let text = String(msg.text || '').trim();
      if (!text && msg.attachments && msg.attachments.length) text = '(клиент прислал вложение без текста: ' + msg.attachments.map(a => a.type).join(', ') + ')';
      if (!text) continue;
      out.push({ json: { user_id, text } });
    }
  }
}
st.seen = st.seen.slice(-300);
return out;

// Отделяем служебные метки от текста для клиента
const raw = String($json.output || '').trim();
const leadLine = (raw.match(/^\[ЗАЯВКА\].*$/m) || [''])[0];
const needManager = /^\[МЕНЕДЖЕР\]/m.test(raw);
const reply = raw.replace(/^\[ЗАЯВКА\].*$/mg, '').replace(/^\[МЕНЕДЖЕР\].*$/mg, '').trim();
const lead = {};
leadLine.replace('[ЗАЯВКА]', '').split(';').forEach(p => { const [k, ...v] = p.split('='); if (k && k.trim()) lead[k.trim()] = v.join('=').trim(); });
const src = $('Разобрать события').item.json;
return { json: { user_id: src.user_id, text: src.text, reply, isLead: !!leadLine, needManager, lead } };

// Instagram принимает до 1000 символов в сообщении — делим длинный ответ по абзацам/предложениям
const st = $getWorkflowStaticData('global');
st.botSent = st.botSent || {};
const out = [];
for (const item of $input.all()) {
  const { user_id, reply } = item.json;
  if (!reply) continue;
  const parts = []; let cur = '';
  for (const piece of reply.split(/(?<=[.!?…])\s+|\n{2,}/)) {
    if ((cur + ' ' + piece).trim().length > 950) { if (cur) parts.push(cur.trim()); cur = piece; }
    else cur = (cur ? cur + ' ' : '') + piece;
  }
  if (cur.trim()) parts.push(cur.trim());
  // запоминаем ДО отправки, чтобы эхо от Instagram не приняли за ответ Алины
  st.botSent[user_id] = (st.botSent[user_id] || []).concat(parts).slice(-20);
  parts.forEach(text => out.push({ json: { user_id, text } }));
}
return out;
